static NSArray<NSButton *> *Buttons(NSView *view){NSMutableArray *all=[NSMutableArray new];if([view isKindOfClass:NSButton.class])[all addObject:view];for(NSView *child in view.subviews)[all addObjectsFromArray:Buttons(child)];return all;}
