 [NSApplication sharedApplication];NSString *directory=argc>1?[NSString stringWithUTF8String:argv[1]]:NSTemporaryDirectory();FYGrammarCatalog *catalog=[FYGrammarCatalog new];FYLearningStore *store=Store([directory stringByAppendingPathComponent:@"grammar-page-builder.sqlite"]);AppDelegate *app=App(store,Analyzer(catalog),catalog);[app.mainWindow.contentView layoutSubtreeIfNeeded];Tick();
 Require(app.grammarTabButtons.count==3&&app.grammarTabUnderlines.count==3&&app.selectedGrammarTab==1,@"complete native card keeps original three tabs and default grammar tab");NSUInteger index=0;for(NSButton *tab in app.grammarTabButtons){Require(tab.tag==(NSInteger)index++&&tab.target==app&&tab.action==@selector(selectGrammarTab:),@"native tabs target original Host and original selector/index");Require(tab.font.pointSize==13,@"native tab13pt font unchanged");}
