 NSString *source=@"猫は学校へ。";FYGrammarItem *a=[FYGrammarItem new];a.name=@"合成结构";a.matchedText=@"学校へ。";a.matchedRange=NSMakeRange(2,4);FYAnalysisResult *result=[FYAnalysisResult new];result.grammar=@[a];result.structureTitle=@"合成结构标题";result.structureParts=@[@{@"location":@0,@"length":@2,@"text":@"猫は",@"role":@"主体",@"meaning":@"合成说明"},@{@"location":@2,@"length":@4,@"text":@"学校へ。",@"role":@"方向",@"meaning":@"合成说明"}];
 app.selectedGrammarIndex=0;NSView *main=[app structureViewForAnalysis:result source:source quick:NO];Require(main&&app.mainStructureButtons.count==2&&app.mainStructureScrollView.hasHorizontalScroller&&app.mainStructureScrollView.scrollerStyle==NSScrollerStyleOverlay,@"complete main graph creates original horizontal flow and two nodes");Require(app.mainStructureButtons[0].tag==-1&&app.mainStructureButtons[1].tag==0,@"first intersecting grammar tag remains mapped with unassociated node -1");for(NSButton *node in app.mainStructureButtons){Require(node.target==app&&node.action==@selector(selectMainStructure:)&&node.layer.cornerRadius==14,@"main structure target/action/corner preserved");}
